<?php
require __DIR__.'/../bootstrap.php';
require_login();
$u=current_user();
$pdo=db();

// Lightweight JSON endpoint used by the dashboard's live-tail panel.
if (($_GET['ajax'] ?? '') === 'live-tail') {
    $since=max(0,(int)($_GET['since'] ?? 0));
    $sql="SELECT l.id,l.method,l.path,l.status_code,l.latency_ms,l.token_id,l.ip_hash,l.created_at,t.token_prefix
          FROM api_request_logs l LEFT JOIN link_api_tokens t ON t.id=l.token_id
          WHERE l.user_id=? AND l.id>? ORDER BY l.id DESC LIMIT 30";
    $s=$pdo->prepare($sql);$s->execute([(int)$u['id'],$since]);
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode(['data'=>$s->fetchAll(),'now'=>time()],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;
}

if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    $action=(string)($_POST['action']??'');
    if($action==='create'){
        $label=trim((string)($_POST['label']??''))?:'API Token';
        $raw='pc_live_'.bin2hex(random_bytes(24));
        $pdo->prepare('INSERT INTO link_api_tokens(user_id,label,token_hash,token_prefix,created_at) VALUES(?,?,?,?,NOW())')
            ->execute([(int)$u['id'],$label,hash('sha256',$raw),substr($raw,0,14)]);
        $_SESSION['_api_token_once']=$raw;
        redirect('/settings/link-api/');
    }
    if($action==='toggle'){
        $id=(int)($_POST['id']??0);
        $s=$pdo->prepare('SELECT revoked_at FROM link_api_tokens WHERE id=? AND user_id=?');$s->execute([$id,(int)$u['id']]);$cur=$s->fetch();
        if($cur){
            $new=$cur['revoked_at']?null:date('Y-m-d H:i:s');
            $pdo->prepare('UPDATE link_api_tokens SET revoked_at=? WHERE id=? AND user_id=?')->execute([$new,$id,(int)$u['id']]);
            flash('success',$new?'Token disabled.':'Token activated.');
        }
        redirect('/settings/link-api/');
    }
    if($action==='delete'){
        $id=(int)($_POST['id']??0);
        $pdo->prepare('DELETE FROM link_api_tokens WHERE id=? AND user_id=?')->execute([$id,(int)$u['id']]);
        flash('success','Token deleted.');redirect('/settings/link-api/');
    }
    if($action==='create_webhook'){
        $url=trim((string)($_POST['url']??''));
        if(!webhook_target_is_safe($url)){flash('error','Enter a valid webhook URL.');redirect('/settings/link-api/#webhooks');}
        $events=array_values(array_filter(array_map('trim',explode(',',(string)($_POST['events']??'click,milestone,expired')))));
        $secret=bin2hex(random_bytes(20));
        $_SESSION['_webhook_secret_once']=$secret;
        $pdo->prepare('INSERT INTO link_webhooks(user_id,url,secret,events_json,active,created_at) VALUES(?,?,?,?,1,NOW())')->execute([(int)$u['id'],$url,$secret,json_encode($events,JSON_UNESCAPED_SLASHES)]);
        flash('success','Webhook endpoint added.');redirect('/settings/link-api/#webhooks');
    }
    if($action==='toggle_webhook'){
        $id=(int)($_POST['id']??0);$pdo->prepare('UPDATE link_webhooks SET active=IF(active=1,0,1) WHERE id=? AND user_id=?')->execute([$id,(int)$u['id']]);flash('success','Webhook status updated.');redirect('/settings/link-api/#webhooks');
    }
    if($action==='delete_webhook'){
        $id=(int)($_POST['id']??0);$pdo->prepare('DELETE FROM link_webhooks WHERE id=? AND user_id=?')->execute([$id,(int)$u['id']]);flash('success','Webhook endpoint deleted.');redirect('/settings/link-api/#webhooks');
    }
    if($action==='retry_webhook'){
        $id=(int)($_POST['delivery_id']??0);
        $s=$pdo->prepare('SELECT d.*,h.url,h.secret,h.user_id FROM link_webhook_deliveries d JOIN link_webhooks h ON h.id=d.webhook_id WHERE d.id=? AND h.user_id=? LIMIT 1');
        $s->execute([$id,(int)$u['id']]);$d=$s->fetch();
        if(!$d){flash('error','Webhook delivery not found.');redirect('/settings/link-api/#webhooks');}
        $payload=(string)($d['request_body']??'');
        if($payload===''){$payload=json_encode(['event'=>$d['event_name'],'redelivery'=>true,'timestamp'=>gmdate('c')],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}
        $sig=hash_hmac('sha256',$payload,(string)$d['secret']);
        $ch=curl_init((string)$d['url']);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$payload,CURLOPT_HTTPHEADER=>['Content-Type: application/json','X-PocketCat-Signature: '.$sig],CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT_MS=>500,CURLOPT_TIMEOUT_MS=>3000]);
        $body=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);
        $pdo->prepare('INSERT INTO link_webhook_deliveries(webhook_id,event_name,status_code,response_body,request_body,attempt_count,created_at) VALUES(?,?,?,?,?,?,NOW())')
            ->execute([(int)$d['webhook_id'],$d['event_name'].' (retry)',$status,substr((string)$body,0,10000),$payload,(int)($d['attempt_count']??1)+1]);
        flash($status>=200&&$status<300?'success':'error',$status>=200&&$status<300?'Webhook redelivered successfully.':'Webhook retry returned HTTP '.$status.'.');
        redirect('/settings/link-api/#webhooks');
    }
}

$tokenOnce=$_SESSION['_api_token_once']??null;unset($_SESSION['_api_token_once']);$webhookSecretOnce=$_SESSION['_webhook_secret_once']??null;unset($_SESSION['_webhook_secret_once']);
$q=$pdo->prepare('SELECT id,label,token_prefix,created_at,last_used_at,revoked_at FROM link_api_tokens WHERE user_id=? ORDER BY id DESC');$q->execute([(int)$u['id']]);$tokens=$q->fetchAll();

$range=in_array((string)($_GET['range']??'24h'),['24h','7d','30d'],true)?(string)$_GET['range']:'24h';
$hours=$range==='24h'?24:($range==='7d'?168:720);
$since=date('Y-m-d H:i:s',time()-$hours*3600);

$stat=function(string $sql,array $params=[] )use($pdo){$s=$pdo->prepare($sql);$s->execute($params);return $s->fetchColumn();};
$total=(int)$stat('SELECT COUNT(*) FROM api_request_logs WHERE user_id=? AND created_at>=?',[(int)$u['id'],$since]);
$success=(int)$stat('SELECT COUNT(*) FROM api_request_logs WHERE user_id=? AND created_at>=? AND status_code BETWEEN 200 AND 399',[(int)$u['id'],$since]);
$successRate=$total?round($success/$total*100,2):100;
$avg=(float)($stat('SELECT COALESCE(AVG(latency_ms),0) FROM api_request_logs WHERE user_id=? AND created_at>=?',[(int)$u['id'],$since])??0);
$activeTokens=(int)$stat('SELECT COUNT(*) FROM link_api_tokens WHERE user_id=? AND revoked_at IS NULL',[(int)$u['id']]);
$endpoints=(int)$stat('SELECT COUNT(*) FROM link_webhooks WHERE user_id=? AND active=1',[(int)$u['id']]);
$apiLimit=(int)policy_global('api_rate_per_minute',120);$minuteCount=(int)$stat('SELECT COUNT(*) FROM api_request_logs WHERE user_id=? AND created_at>=?',[(int)$u['id'],date('Y-m-d H:i:s',time()-60)]);$minuteRemaining=max(0,$apiLimit-$minuteCount);$dayCount=(int)$stat('SELECT COUNT(*) FROM api_request_logs WHERE user_id=? AND created_at>=?',[(int)$u['id'],date('Y-m-d 00:00:00')]);$quotaPct=$apiLimit?min(100,round($minuteCount/$apiLimit*100)):0;

$timeline=[];
if($range==='24h'){
  $s=$pdo->prepare("SELECT DATE_FORMAT(created_at,'%Y-%m-%d %H:00:00') label,COUNT(*) n FROM api_request_logs WHERE user_id=? AND created_at>=? GROUP BY label ORDER BY label");
}else{
  $s=$pdo->prepare("SELECT DATE(created_at) label,COUNT(*) n FROM api_request_logs WHERE user_id=? AND created_at>=? GROUP BY label ORDER BY label");
}
$s->execute([(int)$u['id'],$since]);$timeline=$s->fetchAll();$maxTimeline=1;foreach($timeline as $r)$maxTimeline=max($maxTimeline,(int)$r['n']);
$statusRows=$pdo->prepare("SELECT CASE WHEN status_code BETWEEN 200 AND 299 THEN '2xx' WHEN status_code BETWEEN 400 AND 499 THEN '4xx' WHEN status_code>=500 THEN '5xx' ELSE '3xx/other' END grp,COUNT(*) n FROM api_request_logs WHERE user_id=? AND created_at>=? GROUP BY grp ORDER BY n DESC");$statusRows->execute([(int)$u['id'],$since]);$statuses=$statusRows->fetchAll();
$endpointRows=$pdo->prepare('SELECT method,path,COUNT(*) n,ROUND(AVG(latency_ms),1) avg_ms FROM api_request_logs WHERE user_id=? AND created_at>=? GROUP BY method,path ORDER BY n DESC LIMIT 10');$endpointRows->execute([(int)$u['id'],$since]);$topEndpoints=$endpointRows->fetchAll();
$tokenUsage=$pdo->prepare("SELECT COALESCE(t.label,'Unknown token') label,COALESCE(t.token_prefix,'-') prefix,COUNT(l.id) n FROM api_request_logs l LEFT JOIN link_api_tokens t ON t.id=l.token_id WHERE l.user_id=? AND l.created_at>=? GROUP BY l.token_id ORDER BY n DESC LIMIT 10");$tokenUsage->execute([(int)$u['id'],$since]);$tokenRows=$tokenUsage->fetchAll();
$geo=$pdo->prepare('SELECT ip_hash,COUNT(*) n,MIN(created_at) first_seen,MAX(created_at) last_seen FROM api_request_logs WHERE user_id=? AND created_at>=? GROUP BY ip_hash ORDER BY n DESC LIMIT 20');$geo->execute([(int)$u['id'],$since]);$geoRows=$geo->fetchAll();

$method=(string)($_GET['method']??'');$statusFilter=(int)($_GET['status']??0);$tokenFilter=(int)($_GET['token']??0);$dateFrom=trim((string)($_GET['from']??''));$dateTo=trim((string)($_GET['to']??''));
$where=['l.user_id=?'];$params=[(int)$u['id']];if($method&&in_array($method,['GET','POST','PATCH','DELETE','PUT'],true)){$where[]='l.method=?';$params[]=$method;}if($statusFilter>=100&&$statusFilter<=599){$where[]='l.status_code=?';$params[]=$statusFilter;}if($tokenFilter>0){$where[]='l.token_id=?';$params[]=$tokenFilter;}if($dateFrom){$where[]='l.created_at>=?';$params[]=$dateFrom.' 00:00:00';}if($dateTo){$where[]='l.created_at<=?';$params[]=$dateTo.' 23:59:59';}$whereSql=implode(' AND ',$where);
$logs=$pdo->prepare("SELECT l.*,COALESCE(t.label,'Deleted token') token_label,COALESCE(t.token_prefix,'-') token_prefix FROM api_request_logs l LEFT JOIN link_api_tokens t ON t.id=l.token_id WHERE $whereSql ORDER BY l.id DESC LIMIT 100");$logs->execute($params);$requestLogs=$logs->fetchAll();
$hooks=$pdo->prepare('SELECT h.id,h.url,h.active,h.events_json,h.created_at,COUNT(d.id) deliveries FROM link_webhooks h LEFT JOIN link_webhook_deliveries d ON d.webhook_id=h.id WHERE h.user_id=? GROUP BY h.id ORDER BY h.id DESC');$hooks->execute([(int)$u['id']]);$webhooks=$hooks->fetchAll();
$delivery=$pdo->prepare('SELECT d.*,h.url FROM link_webhook_deliveries d JOIN link_webhooks h ON h.id=d.webhook_id WHERE h.user_id=? ORDER BY d.id DESC LIMIT 50');$delivery->execute([(int)$u['id']]);$deliveries=$delivery->fetchAll();
require __DIR__.'/../includes/header.php';
?>
<div class="page-head"><div><span class="eyebrow">DEVELOPER API</span><h1>API access</h1><p>Bearer tokens for link CRUD, analytics and signed webhooks.</p></div><div class="api-range"><a class="pill <?= $range==='24h'?'active':'' ?>" href="?range=24h">24h</a><a class="pill <?= $range==='7d'?'active':'' ?>" href="?range=7d">7d</a><a class="pill <?= $range==='30d'?'active':'' ?>" href="?range=30d">30d</a></div></div>
<?php if($tokenOnce): ?><section class="card api-token-once"><h2>Token created</h2><p class="muted">Copy this token now. For security, the full token is only displayed once.</p><div class="copy-box api-token-copy-box"><input id="newApiToken" class="api-token-value" type="text" readonly value="<?=e($tokenOnce)?>" aria-label="New API token"><button class="btn small" type="button" data-copy-token="newApiToken">Copy token</button><span class="copy-feedback" aria-live="polite"></span></div></section><?php endif; ?><?php if($webhookSecretOnce): ?><section class="card api-token-once"><h2>Webhook secret created</h2><p class="muted">Store this signing secret securely. It is not shown again.</p><div class="copy-box"><code id="newWebhookSecret"><?=e($webhookSecretOnce)?></code><button class="btn small" type="button" data-copy-target="newWebhookSecret">Copy secret</button></div></section><?php endif; ?>
<section class="card"><form method="post" class="api-create-form"><?=csrf_field()?><input type="hidden" name="action" value="create"><label data-help-key="link-api">Token label<input name="label" placeholder="Production app" maxlength="120"></label><button class="btn">Create token</button></form></section>
<section class="stats api-stats"><div class="card stat"><span>Total Requests</span><strong><?=number_format($total)?></strong><small><?=e($range)?> window</small></div><div class="card stat"><span>Success Rate</span><strong><?=e(number_format($successRate,2))?>%</strong><small>Target &gt;99%</small></div><div class="card stat"><span>Average Latency</span><strong><?=e(number_format($avg,1))?> ms</strong><small>End-to-end API time</small></div><div class="card stat"><span>Active Tokens / Endpoints</span><strong><?=number_format($activeTokens)?> / <?=number_format($endpoints)?></strong><small>Credentials / webhooks</small></div></section>
<section class="card api-quota"><div><h2>Rate Limit Usage</h2><p class="muted">Current API request usage against the configured per-minute limit.</p></div><div class="quota-meter"><span style="width:<?=$quotaPct?>%"></span></div><div class="quota-meta"><strong><?=number_format($minuteCount)?> / <?=number_format($apiLimit)?></strong><span><?=number_format($minuteRemaining)?> remaining this minute · <?=number_format($dayCount)?> today</span></div></section>
<div class="api-dashboard-grid">
<section class="card"><div class="section-head"><div><h2>Traffic & Usage</h2><p class="muted">Requests per hour for 24h, or per day for longer ranges.</p></div></div><div class="api-bars"><?php foreach($timeline as $r): ?><div class="api-bar-col"><strong><?=number_format((int)$r['n'])?></strong><i style="height:<?=max(8,round(((int)$r['n']/$maxTimeline)*150))?>px"></i><small><?=e($range==='24h'?substr($r['label'],11,5):substr($r['label'],5))?></small></div><?php endforeach;if(!$timeline):?><div class="empty-state">No API requests in this period.</div><?php endif;?></div></section>
<section class="card"><h2>Status Code Breakdown</h2><?php $statusTotal=array_sum(array_map(fn($x)=>(int)$x['n'],$statuses));$status2xx=0;foreach($statuses as $sr){if(($sr['grp']??'')==='2xx'){$status2xx=(int)$sr['n'];break;}}?><div class="api-donut-wrap"><div class="api-donut" style="--p2:<?=($statusTotal?round(($status2xx/$statusTotal)*100):0)?>%"><span><?=number_format($statusTotal)?><small>requests</small></span></div><div class="api-status-list"><?php foreach($statuses as $r):$pct=$statusTotal?round((int)$r['n']/$statusTotal*100,1):0;?><div><span><?=e($r['grp'])?></span><b><?=number_format((int)$r['n'])?> <small class="muted">(<?=e($pct)?>%)</small></b></div><?php endforeach;if(!$statuses):?><p class="muted">No status data yet.</p><?php endif;?></div></div></section>
</div>
<div class="api-dashboard-grid"><section class="card"><h2>Top Endpoints</h2><div class="table-wrap"><table><thead><tr><th>Method</th><th>Endpoint</th><th>Requests</th><th>Avg latency</th></tr></thead><tbody><?php foreach($topEndpoints as $r):?><tr><td><span class="api-method"><?=e($r['method'])?></span></td><td><code><?=e($r['path'])?></code></td><td><?=number_format((int)$r['n'])?></td><td><?=e($r['avg_ms'])?> ms</td></tr><?php endforeach;if(!$topEndpoints):?><tr><td colspan="4" class="muted">No endpoint data.</td></tr><?php endif;?></tbody></table></div></section>
<section class="card"><h2>Token-Level Usage</h2><div class="table-wrap"><table><thead><tr><th>Token</th><th>Requests</th></tr></thead><tbody><?php foreach($tokenRows as $r):?><tr><td><strong><?=e($r['label'])?></strong><br><code><?=e($r['prefix'])?>…</code></td><td><?=number_format((int)$r['n'])?></td></tr><?php endforeach;if(!$tokenRows):?><tr><td colspan="2" class="muted">No usage yet.</td></tr><?php endif;?></tbody></table></div></section></div>
<section class="card"><div class="section-head"><div><h2>Tokens</h2><p class="muted">Activate, disable, delete, and copy the newly-created secret.</p></div></div><?php foreach($tokens as $t):?><div class="api-token-row"><div><strong><?=e($t['label'])?></strong><div><code><?=e($t['token_prefix'])?>…</code> · <span class="badge <?= $t['revoked_at']?'status-draft':'status-published' ?>"><?=e($t['revoked_at']?'Disabled':'Active')?></span></div><small class="muted">Created <?=e($t['created_at'])?><?= $t['last_used_at']?' · Last used '.e($t['last_used_at']):'' ?></small></div><div class="api-row-actions"><button class="edit-btn api-copy-prefix" type="button" data-copy="<?=e($t['token_prefix'])?>">Copy prefix</button><form method="post" onsubmit="return confirm('<?= $t['revoked_at']?'Activate':'Disable' ?> this token?')"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$t['id']?>"><button class="edit-btn" type="submit"><?= $t['revoked_at']?'Activate':'Disable' ?></button></form><form method="post" onsubmit="return confirm('Permanently delete this token?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$t['id']?>"><button class="edit-btn danger" type="submit">Delete</button></form></div></div><?php endforeach;if(!$tokens):?><p class="muted">No API tokens yet.</p><?php endif;?></section>
<section class="card" id="webhooks"><div class="section-head"><div><h2>Webhook Delivery System</h2><p class="muted">Register endpoints, manage active state, and inspect signed delivery history.</p></div></div><form method="post" class="api-webhook-form"><?=csrf_field()?><input type="hidden" name="action" value="create_webhook"><label>Target URL<input type="url" name="url" placeholder="https://example.com/pocketcat" required></label><label>Events<input name="events" value="click,milestone,expired" placeholder="click,milestone,expired"></label><button class="btn" type="submit">Add endpoint</button></form><?php if($webhooks):?><div class="webhook-list"><?php foreach($webhooks as $h):?><div class="api-token-row"><div><strong><?=e($h['url'])?></strong><small class="muted">Events: <?=e(implode(', ',(array)json_decode((string)$h['events_json'],true)))?> · <?=e($h['deliveries'])?> deliveries</small></div><div class="api-row-actions"><span class="badge <?= $h['active']?'status-published':'status-draft' ?>"><?= $h['active']?'Active':'Disabled' ?></span><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle_webhook"><input type="hidden" name="id" value="<?=$h['id']?>"><button class="edit-btn" type="submit"><?= $h['active']?'Disable':'Activate' ?></button></form><form method="post" onsubmit="return confirm('Delete this webhook endpoint?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_webhook"><input type="hidden" name="id" value="<?=$h['id']?>"><button class="edit-btn danger" type="submit">Delete</button></form></div></div><?php endforeach;?></div><?php else:?><p class="muted">No webhooks registered.</p><?php endif;?></section>
<section class="card"><h2>Delivery Logs</h2><div class="table-wrap"><table><thead><tr><th>Event ID</th><th>Target URL</th><th>Event</th><th>Timestamp</th><th>HTTP</th><th>Actions</th></tr></thead><tbody><?php foreach($deliveries as $d):?><tr><td>#<?=e($d['id'])?></td><td><code><?=e($d['url'])?></code></td><td><?=e($d['event_name'])?></td><td><?=e($d['created_at'])?></td><td><?=e($d['status_code'])?></td><td><button type="button" class="edit-btn inspect-delivery" data-delivery="<?=e(json_encode(['id'=>$d['id'],'request_headers'=>(string)($d['request_headers']??''),'request_body'=>(string)($d['request_body']??''),'response_headers'=>(string)($d['response_headers']??''),'response_body'=>(string)($d['response_body']??'')],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))?>">Inspect payload</button><form method="post" style="margin-top:8px"><?=csrf_field()?><input type="hidden" name="action" value="retry_webhook"><input type="hidden" name="delivery_id" value="<?=$d['id']?>"><button class="edit-btn" type="submit">Redeliver</button></form></td></tr><?php endforeach;if(!$deliveries):?><tr><td colspan="6" class="muted">No webhook deliveries yet.</td></tr><?php endif;?></tbody></table></div></section>
<section class="card"><div class="section-head"><div><h2>Developer Logs & Filters</h2><p class="muted">Search request history by status, token, method and date range.</p></div><button class="btn small" id="liveTailToggle" type="button">Live Tail: Off</button></div><form class="api-filter" method="get"><input type="hidden" name="range" value="<?=e($range)?>"><label>Method<select name="method"><option value="">All</option><?php foreach(['GET','POST','PATCH','PUT','DELETE'] as $m):?><option <?=$method===$m?'selected':''?>><?=$m?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="0">All</option><?php foreach([200,201,204,400,401,403,404,422,429,500,503] as $st):?><option value="<?=$st?>" <?=$statusFilter===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select></label><label>Token<select name="token"><option value="0">All</option><?php foreach($tokens as $t):?><option value="<?=$t['id']?>" <?=$tokenFilter===(int)$t['id']?'selected':''?>><?=e($t['label'])?></option><?php endforeach;?></select></label><label>From<input type="date" name="from" value="<?=e($dateFrom)?>"></label><label>To<input type="date" name="to" value="<?=e($dateTo)?>"></label><button class="btn" type="submit">Filter</button></form><div id="liveTail" class="api-live-tail" hidden></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Method</th><th>Endpoint</th><th>Status</th><th>Latency</th><th>Token</th><th>IP hash</th></tr></thead><tbody><?php foreach($requestLogs as $r):?><tr><td><?=e($r['created_at'])?></td><td><span class="api-method"><?=e($r['method'])?></span></td><td><code><?=e($r['path'])?></code></td><td><span class="api-http s<?=floor((int)$r['status_code']/100)?>"><?=e($r['status_code'])?></span></td><td><?=e($r['latency_ms'])?> ms</td><td><?=e($r['token_label'])?><br><code><?=e($r['token_prefix'])?>…</code></td><td><code><?=e($r['ip_hash'])?></code></td></tr><?php endforeach;if(!$requestLogs):?><tr><td colspan="7" class="muted">No requests match the selected filters.</td></tr><?php endif;?></tbody></table></div></section>
<section class="card"><h2>Geo & IP Analytics</h2><p class="muted">Privacy-safe hashed client IPs are shown instead of raw addresses.</p><div class="table-wrap"><table><thead><tr><th>Client IP hash</th><th>Requests</th><th>First seen</th><th>Last seen</th></tr></thead><tbody><?php foreach($geoRows as $r):?><tr><td><code><?=e($r['ip_hash'])?></code></td><td><?=number_format((int)$r['n'])?></td><td><?=e($r['first_seen'])?></td><td><?=e($r['last_seen'])?></td></tr><?php endforeach;if(!$geoRows):?><tr><td colspan="4" class="muted">No client-origin data yet.</td></tr><?php endif;?></tbody></table></div></section>
<section class="card"><h2>Webhook endpoint</h2><p class="muted">API clients can POST to <code>/api/links/webhooks</code> with <code>url</code>, optional <code>link_id</code>, and <code>events</code>. Webhook payloads are signed with HMAC SHA-256 in <code>X-PocketCat-Signature</code>.</p></section>
