<script>
(function(){
 const copyText=async(text,feedback)=>{try{await navigator.clipboard.writeText(text)}catch(e){const t=document.createElement('textarea');t.value=text;document.body.appendChild(t);t.select();document.execCommand('copy');t.remove()}if(feedback){feedback.textContent='Copied';setTimeout(()=>feedback.textContent='',1400)}};
 document.querySelectorAll('[data-copy-token]').forEach(b=>b.addEventListener('click',()=>{const e=document.getElementById(b.dataset.copyToken);if(e)copyText(e.value||e.textContent.trim(),b.parentElement.querySelector('.copy-feedback'))}));
 document.querySelectorAll('[data-copy-target]').forEach(b=>b.addEventListener('click',()=>{const e=document.getElementById(b.dataset.copyTarget);if(e)copyText(e.value||e.textContent.trim(),b.parentElement.querySelector('.copy-feedback'))}));
 document.querySelectorAll('.api-copy-prefix').forEach(b=>b.addEventListener('click',()=>copyText(b.dataset.copy,b)));
 const toggle=document.getElementById('liveTailToggle'),box=document.getElementById('liveTail');let timer=null,last=0;
 function render(rows){box.hidden=false;box.innerHTML=rows.map(r=>`<div>[${r.created_at}] ${r.method} ${r.path} → ${r.status_code} · ${r.latency_ms}ms · ${r.token_prefix||'-'}…</div>`).join('')||'<div>No new requests.</div>';}
 async function poll(){try{const j=await fetch('?ajax=live-tail&since='+encodeURIComponent(last),{cache:'no-store'}).then(r=>r.json());if(j.data?.length){last=Math.max(...j.data.map(x=>Number(x.id)||0),last);render(j.data)}}catch(e){}}
 toggle?.addEventListener('click',()=>{if(timer){clearInterval(timer);timer=null;toggle.textContent='Live Tail: Off';box.hidden=true;return}toggle.textContent='Live Tail: On';poll();timer=setInterval(poll,3000)});
 const modal=document.getElementById('apiPayloadModal');const fields={reqH:document.getElementById('apiReqHeaders'),reqB:document.getElementById('apiReqBody'),resH:document.getElementById('apiResHeaders'),resB:document.getElementById('apiResBody')};
 document.querySelectorAll('.inspect-delivery').forEach(b=>b.addEventListener('click',()=>{try{const d=JSON.parse(b.dataset.delivery);fields.reqH.textContent=d.request_headers||'—';fields.reqB.textContent=d.request_body||'—';fields.resH.textContent=d.response_headers||'—';fields.resB.textContent=d.response_body||'—';modal.hidden=false;document.body.classList.add('modal-open')}catch(e){}}));
 document.querySelectorAll('[data-close-api-modal]').forEach(x=>x.addEventListener('click',()=>{modal.hidden=true;document.body.classList.remove('modal-open')}));
})();
</script>
